    auto rh = robin_hood::hash<T>{}(val);
    auto fn = hash::FNV1a<T>{}(val);
    std::cout << fmt::hex(val) << " | " << fmt::hex(id) << " | " << fmt::hex(sh) << " | "
              << fmt::hex(fn) << " | " << fmt::hex(rh) << " | " << fmt::bin(rh) << std::endl;
}

